<template><el-card class="login"><h2>TunnelMesh</h2><el-form @submit.prevent="submit"><el-form-item label="Username"><el-input v-model="username" autocomplete="username"/></el-form-item><el-form-item label="Password"><el-input v-model="password" type="password" show-password autocomplete="current-password"/></el-form-item><el-button type="primary" native-type="submit" :loading="loading">Sign in</el-button><el-alert v-if="error" type="error" :title="error"/></el-form></el-card></template>
<script setup lang="ts">import {ref} from 'vue'; import {useRouter} from 'vue-router'; import {useAuthStore} from '../stores/auth'; const username=ref(''),password=ref(''),error=ref(''),loading=ref(false),router=useRouter(),auth=useAuthStore(); async function submit(){loading.value=true;error.value='';try{await auth.login(username.value,password.value);router.push('/')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}</script>
<style scoped>.login{max-width:420px;margin:15vh auto}</style>
